import type { ChildProcess } from 'child_process';
import type { Framework } from '../services/ProjectDetectionService';
import type { TemplateBundle } from '../services/templates/viteReactTs';
import type { DesignContextEntry } from './contracts';

export type WorktreeCreationOptions = {
  requiredProjectFiles?: readonly string[];
};

export interface WorktreeManagerLike {
  createWorktrees(
    sessionId: string,
    count: number,
    instanceKeyPrefix?: string,
    options?: WorktreeCreationOptions,
  ): Promise<string[]>;
  forkWorktreesFrom?(
    sourceWorktreePath: string,
    sessionId: string,
    count: number,
    instanceKeyPrefix?: string,
  ): Promise<string[]>;
  getDiff(worktreePath: string): Promise<string>;
  getGitRoot?(): Promise<string>;
  cleanupSession(
    sessionId: string,
    freshDestinationParent?: string,
  ): Promise<void>;
  getFreePort(): Promise<number>;
  findFreePortFrom(startPort: number): Promise<number>;
  releasePort?(port: number): void;
  startDevServer(
    worktreePath: string,
    port: number,
    cmd: string,
    args: string[],
    env: Record<string, string>,
  ): Promise<ChildProcess>;
  stopDevServer(proc: ChildProcess, timeoutMs?: number): Promise<void>;
  getProjectCwdInWorktree(worktreePath: string): Promise<string>;
  getChangedFiles?(worktreePath: string): Promise<string[]>;
  createFreshWorktrees?(
    sessionId: string,
    count: number,
    template: TemplateBundle,
    designContext: ReadonlyArray<DesignContextEntry | undefined> | undefined,
    destinationParent: string,
  ): Promise<string[]>;
}

type DevServerProjectEnvironment = {
  projectPath: string;
  framework: Exclude<Framework, 'static'>;
  packageManager: string;
  devCommand: string;
  defaultPort?: number;
  buildDevCommand?: (port: number) => {
    cmd: string;
    args: string[];
    env: Record<string, string>;
  };
};

type StaticProjectEnvironment = {
  projectPath: string;
  framework: 'static';
  entryPath?: string;
};

export type ProjectEnvironment =
  DevServerProjectEnvironment | StaticProjectEnvironment;
